import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student


def make_student(student_id: str, last_name: str, first_name: str) -> Student:
    return Student(student_id, last_name, first_name, "A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("1", "Halloway", "Juno"),
            make_student("2", "Dunmere", "Piet"),
            make_student("3", "Okafor", "Ruth"),
            make_student("4", "Brink", "Sam"),
        ]

    def test_sorted_by_last_name_and_chunked_into_rows(self):
        lines = seating_rows(self.students, 2)
        self.assertEqual(
            lines,
            [
                "Row 1: Brink, Sam | Dunmere, Piet",
                "Row 2: Halloway, Juno | Okafor, Ruth",
            ],
        )

    def test_partial_last_row(self):
        lines = seating_rows(self.students[:3], 2)
        self.assertEqual(
            lines,
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Okafor, Ruth",
            ],
        )

    def test_seats_larger_than_class_gives_one_row(self):
        lines = seating_rows(self.students, 10)
        self.assertEqual(
            lines,
            ["Row 1: Brink, Sam | Dunmere, Piet | Halloway, Juno | Okafor, Ruth"],
        )

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
